discrete ControlSystem
port:
    event input real StartSignal;
    event input real SafetyCheckPassed;
    event input real LaserPreheatComplete;
    event input real TaskCompleted;
    event input real AbnormalCondition;
    event input real FaultResolved;
state:
    initial state StandbyState
        when entry() then
            statehold(10);
        end;
        when receive(StartSignal) then
            transition(PrepareState);
        end;
    end;

    state PrepareState
        when entry() then
            statehold(10);
        end;
        when receive(SafetyCheckPassed) then
            transition(RunningState);
        end;
        when receive(LaserPreheatComplete) then
            transition(RunningState);
        end;
    end;

    state RunningState
        when entry() then
            statehold(10);
        end;
        when receive(TaskCompleted) then
            transition(StandbyState);
        end;
        when receive(AbnormalCondition) then
            transition(StopFaultState);
        end;
    end;

    state StopFaultState
        when entry() then
            statehold(10);
        end;
        when receive(FaultResolved) then
            transition(StandbyState);
        end;
    end;
end;
end;

discrete LaserSystem
port:
    event input real ControllerPowerOn;
    event input real ReachedWorkingTemperature;
    event input real TaskEndOrEmergencyStop;
state:
    initial state OffState
        when entry() then
            statehold(10);
        end;
        when receive(ControllerPowerOn) then
            transition(PreheatState);
        end;
    end;

    state PreheatState
        when entry() then
            statehold(10);
        end;
        when receive(ReachedWorkingTemperature) then
            transition(WorkingState);
        end;
    end;

    state WorkingState
        when entry() then
            statehold(10);
        end;
        when receive(TaskEndOrEmergencyStop) then
            transition(OffState);
        end;
    end;
end;
end;

discrete WorktableSystem
port:
    event input real MoveInstruction;
    event input real ArrivedAtDestination;
    event input real CuttingProcessEnd;
state:
    initial state StationaryState
        when entry() then
            statehold(10);
        end;
        when receive(MoveInstruction) then
            transition(MovingState);
        end;
    end;

    state MovingState
        when entry() then
            statehold(10);
        end;
        when receive(ArrivedAtDestination) then
            transition(StationaryState);
        end;
        when receive(CuttingProcessEnd) then
            transition(StationaryState);
        end;
    end;
end;
end;

discrete CoolingSystem
port:
    event input real TemperatureExceedsThreshold;
    event input real TemperatureBelowThreshold;
state:
    initial state InactiveState
        when entry() then
            statehold(10);
        end;
        when receive(TemperatureExceedsThreshold) then
            transition(CirculatingState);
        end;
    end;

    state CirculatingState
        when entry() then
            statehold(10);
        end;
        when receive(TemperatureBelowThreshold) then
            transition(InactiveState);
        end;
    end;
end;
end;

couple LaserCuttingSystem
import architectureModels.ControlSystem as ControlSys;
import architectureModels.LaserSystem as LaserSys;
import architectureModels.WorktableSystem as WorktableSys;
import architectureModels.CoolingSystem as CoolingSys;
part:
    ControlSys controlInstance;
    LaserSys laserInstance;
    WorktableSys worktableInstance;
    CoolingSys coolingInstance;
connection:
    connect(laserInstance.PowerStatus, controlInstance.StartSignal);
    connect(laserInstance.TemperatureStatus, controlInstance.SafetyCheckPassed);
    connect(laserInstance.TemperatureStatus, controlInstance.LaserPreheatComplete);
    connect(laserInstance.OperationStatus, controlInstance.TaskCompleted);
    connect(laserInstance.EmergencyStatus, controlInstance.AbnormalCondition);
    connect(laserInstance.PowerStatus, controlInstance.FaultResolved);

    connect(worktableInstance.MoveStatus, controlInstance.MoveCommand);
    connect(worktableInstance.PositionStatus, controlInstance.PositionReached);
    connect(worktableInstance.CuttingStatus, controlInstance.CuttingComplete);

    connect(coolingInstance.TemperatureAlert, controlInstance.HighTemperatureAlert);
    connect(coolingInstance.TemperatureStatus, controlInstance.NormalTemperature);
end;
